 1→import type {
 2→  ClientInterface,
 3→  SyncServiceInterface,
 4→  UserProfile,
 5→} from "@unomed/react-native-matrix-sdk";
 6→import { atom } from "jotai";
 7→
 8→type VerificationStatus =
 9→  | "idle"
10→  | "waiting"
11→  | "accepted"
12→  | "sasStarted"
13→  | "emojis"
14→  | "success"
15→  | "failed"
16→  | "cancelled"
17→  | "incomingRequest";
18→
19→type VerificationEmoji = {
20→  symbol: string;
21→  description: string;
22→};
23→
24→const roomList = atom<RoomInterface[]>([]);
25→
26→const roomListLoading = atom<boolean>(true);
27→
28→const matrixClient = atom<ClientInterface | null>(null);
29→
30→const syncService = atom<SyncServiceInterface | null>(null);
31→
32→const profile = atom<UserProfile | null>(null);
33→
34→const verificationStatus = atom<VerificationStatus>("idle");
35→
36→const verificationEmojis = atom<VerificationEmoji[] | null>(null);
37→
38→const verificationSenderName = atom<string | null>(null);
39→
40→export const MatrixAtoms = {
41→  roomList,
42→  roomListLoading,
43→  matrixClient,
44→  syncService,
45→  profile,
46→  verificationStatus,
47→  verificationEmojis,
48→  verificationSenderName,
