  1→import { Block, Text } from "@prototyp/skeletor";
  2→import { useIsFocused } from "@react-navigation/native";
  3→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
  4→import {
  5→  EncryptionState,
  6→  MembershipState_Tags,
  7→  type RoomInfo,
  8→  type RoomMember,
  9→} from "@unomed/react-native-matrix-sdk";
 10→import { useAtomValue } from "jotai";
 11→import { MatrixService } from "modules/matrix-client/services";
 12→import { TimelineAtoms } from "modules/timeline/jotai";
 13→import { useEffect, useMemo, useState } from "react";
 14→import { Alert, Image, StyleSheet } from "react-native";
 15→import Toast from "react-native-toast-message";
 16→import { SettingsListItem } from "screens/settings/fragments";
 17→import {
 18→  Button,
 19→  GoBackHeader,
 20→  Loading,
 21→  RoomImage,
 22→  ScreenLayout,
 23→} from "shared/components";
 24→import { Colors, TextSize } from "shared/styles";
 25→import { ActionButtons, EncryptionStatus, Topic } from "./fragments";
 26→import { LeaveRoom } from "./leave-room/LeaveRoom";
 27→
 28→enum LeaveRoomText {
 29→  NOT_PUBLIC = `Are you sure that you want to leave this room? This room is not public and you won't be able to rejoin without an invite.`,
 30→  EMPTY_ROOM = "Are you sure that you want to leave this room? You're the only person here. If you leave, no one will be able to join in the future, including you.",
 31→  PUBLIC = "Are you sure that you want to leave the room?",
 32→}
 33→
 34→export const RoomDetails: React.FC<
 35→  NativeStackScreenProps<Routes, "roomDetails">
 36→> = ({ navigation, route }) => {
 37→  const { room } = route.params;
 38→  const [roomInfo, setRoomInfo] = useState<RoomInfo | undefined>(undefined);
 39→  const isFocused = useIsFocused();
 40→  const isDirect = useMemo(() => roomInfo?.isDirect, [roomInfo]);
 41→  const isEncrypted = useMemo(
 42→    () => roomInfo?.encryptionState === EncryptionState.Encrypted,
 43→    [roomInfo],
 44→  );
 45→  const hasNoCallOption = useMemo(
 46→    () => (roomInfo?.isPublic && !isEncrypted) || !isEncrypted,
 47→    [roomInfo, isEncrypted],
 48→  );
 49→  const [isLeavingRoom, setIsLeavingRoom] = useState(false);
 50→  const [loading, setLoading] = useState(true);
 51→  const [members, setMembers] = useState<RoomMember[]>([]);
 52→  const [userPowerLevel, setUserPowerLevel] = useState<number | null>(null);
 53→  const isAdmin = useMemo(() => userPowerLevel === 100, [userPowerLevel]);
 54→  const pinnedEventIds = useAtomValue(TimelineAtoms.pinnedEventIds);
 55→
 56→  const otherDirectMembersId = useMemo(() => {
 57→    return members.filter(
 58→      (member) => member.userId !== MatrixService.instance?.userId(),
 59→    )[0]?.userId;
 60→  }, [members]);
 61→
 62→  useEffect(() => {
 63→    if (!isFocused) return;
 64→
 65→    room
 66→      .roomInfo()
 67→      .then(setRoomInfo)
 68→      .catch(console.error)
 69→      .finally(() => {
 70→        setLoading(false);
 71→      });
 72→
 73→    room
 74→      .members()
 75→      .then((r) => setMembers(r.nextChunk(100) ?? []))
 76→      .catch(console.error);
 77→
 78→    MatrixService.getUserPowerLevel(room.id())
 79→      .then(setUserPowerLevel)
 80→      .catch(console.error);
 81→  }, [room, isFocused]);
 82→
 83→  const handleConfirmLeaveRoom = async () => {
 84→    try {
 85→      setIsLeavingRoom(true);
 86→      await MatrixService.leaveRoom(room.id());
 87→      navigation.reset({
 88→        index: 0,
 89→        routes: [{ name: "home" }],
 90→      });
 91→      Toast.show({
 92→        type: "success",
 93→        text1: "Room left successfully",
 94→      });
 95→    } catch (error) {
 96→      console.error(error);
 97→      Toast.show({
 98→        type: "error",
 99→        text1: "Failed to leave room",
100→      });
101→    } finally {
102→      setIsLeavingRoom(false);
103→    }
104→  };
105→
106→  const handleLeaveRoom = async () => {
107→    const isEmptyRoom = Number(members.length) === 1;
108→
109→    const textRoom = isEmptyRoom
110→      ? LeaveRoomText.EMPTY_ROOM
111→      : room.isPublic()
112→        ? LeaveRoomText.PUBLIC
113→        : LeaveRoomText.NOT_PUBLIC;
114→
115→    Alert.alert("Leave Room", textRoom, [
116→      { text: "Cancel", style: "cancel" },
117→      { text: "Leave", onPress: handleConfirmLeaveRoom },
118→    ]);
119→  };
120→
121→  if (loading) return <Loading />;
122→
123→  return (
124→    <ScreenLayout>
125→      {isLeavingRoom && <Loading text="Leaving room..." />}
126→      <Block flex={1} scrollable>
127→        <GoBackHeader
128→          margins={{ marginBottom: 40 }}
129→          rightComp={
130→            !isDirect &&
131→            isAdmin && (
132→              <Button.Wrapper
133→                onPress={() =>
134→                  navigation.navigate("editRoom", {
135→                    room,
136→                  })
137→                }
138→              >
139→                <Text>Edit</Text>
140→              </Button.Wrapper>
141→            )
142→          }
143→        />
144→        <Block align="center" gap={12}>
145→          <RoomImage room={room} width={80} height={80} />
146→          <Text size={TextSize.medium} font="InstrumentSans-Bold">
147→            {room.displayName()}
148→          </Text>
149→          {isDirect && roomInfo?.heroes[0]?.userId && (
150→            <Text color={Colors.white50}>{roomInfo?.heroes[0]?.userId}</Text>
151→          )}
152→          <EncryptionStatus roomInfo={roomInfo} />
153→        </Block>
154→        <ActionButtons
155→          isDirect={!!isDirect}
156→          room={room}
157→          members={members}
158→          hasNoCallOption={hasNoCallOption}
159→        />
160→        <Topic room={room} topic={roomInfo?.topic} isAdmin={isAdmin} />
161→        <Block
162→          border={{ borderRadius: 16 }}
163→          width="100%"
164→          background={Colors.white5}
165→          margins={{ marginBottom: 20 }}
166→        >
167→          <SettingsListItem
168→            title="Notifications"
169→            icon={require("assets/icons/bell.png")}
170→            showSeparator
171→            onPress={() => navigation.navigate("roomNotifications")}
172→          />
173→          {isDirect ? (
174→            <Button.Wrapper
