 474→  /** Manually refresh the room list and update the atom */
 475→  public static refreshRoomList = async () => {
 476→    if (!this.instance) return;
 477→
 478→    try {
 479→      const roomsArray = this.getRooms();
 480→
 481→      const sortedRooms = await Promise.all(
 482→        roomsArray.map(async (room) => ({
 483→          room,
 484→          timestamp: (await room.latestEvent())?.timestamp || 0,
 485→        })),
 486→      );
 487→
 488→      const filteredAndSortedRooms = sortedRooms
 489→        .filter(({ room }) => {
 490→          const membership = room.membership();
 491→
 492→          return (
 493→            membership !== Membership.Banned &&
 494→            membership !== Membership.Left &&
 495→            membership !== Membership.Knocked
 496→          );
 497→        })
 498→        .sort((a, b) => {
 499→          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
 500→          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
 501→          if (aInvited !== bInvited) return bInvited - aInvited;
 502→
 503→          return Number(b.timestamp) - Number(a.timestamp);
 504→        });
 505→
 506→      MatrixJotaiStore.set(
 507→        MatrixAtoms.roomList,
 508→        filteredAndSortedRooms.map(({ room }) => room),
 509→      );
 510→    } catch (error) {
 511→      console.error("Failed to refresh room list:", error);
 512→    }
 513→  };
